graphql.query:
query StudentDashboard($regNo: String!) {
  student(regNo: $regNo) {
    regNo
    name
    email
    bookings { slotId roomCode roomName date startHour endHour bookedAt }
  }
}

query ($roomCode: String, $date: String) {
  rooms { roomCode name seats }
  slots(roomCode: $roomCode, date: $date) { id startHour seatsLeft room { name } }
}

mutation ($regNo: String!, $slotId: ID!) {
  bookSlot(regNo: $regNo, slotId: $slotId) { id roomName date startHour seatsLeft }
}

mutation ($regNo: String!, $slotId: ID!) {
  bookSlot(regNo: $regNo, slotId: $slotId) { id }
}
